// Hyperliquid signing parity with the OFFICIAL hyperliquid-python-sdk (pinned 0.24.0).
// test/fixtures/hyperliquid/vectors.json is generated by gen_vectors.py from the SDK itself; every action Harbour signs
// (orders, builder fee, cancel, leverage, approve agent, withdraw) must produce the SDK's exact action bytes hash and signature.
// A second, independent cross-check runs against the community SDK @nktkas/hyperliquid when it is installed (dev only, skipped otherwise).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { build } from 'esbuild';
import { sign } from 'viem/accounts';
import { encode as msgpack } from '@msgpack/msgpack';
import { readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const src = fileURLToPath(new URL('../src/', import.meta.url));
const V = JSON.parse(readFileSync(new URL('./fixtures/hyperliquid/vectors.json', import.meta.url), 'utf8'));
const out = await build({ stdin: { contents: `export * from './core/perps/hyperliquid';`, resolveDir: src, sourcefile: 'e.ts', loader: 'ts' }, bundle: true, write: false, platform: 'node', format: 'esm', logLevel: 'silent' });
const file = path.join(tmpdir(), `harbour-hl-golden-${process.pid}.mjs`); writeFileSync(file, out.outputFiles[0].text);
const hl = await import(pathToFileURL(file).href);

const sig = async (hash) => hl.toSig(await sign({ hash, privateKey: V.key }));
const same = (got, want) => { assert.equal(BigInt(got.r), BigInt(want.r)); assert.equal(BigInt(got.s), BigInt(want.s)); assert.equal(got.v, want.v); };
const actionOf = (s) => s.kind === 'order'
  ? hl.orderAction([hl.orderWire({ asset: s.asset, isBuy: s.isBuy, price: s.price, size: s.size, reduceOnly: s.reduceOnly, tif: s.tif, szDecimals: s.szDec })], s.builder)
  : s.kind === 'cancel' ? hl.cancelAction([{ asset: s.asset, oid: s.oid }]) : hl.leverageAction(s.asset, s.leverage, s.isCross);

for (const c of V.l1) {
  test(`L1 action matches the official SDK: ${c.name}`, async () => {
    const action = actionOf(c.spec);
    assert.equal(JSON.stringify(action), JSON.stringify(c.action), 'wire shape and key order');
    assert.equal(hl.actionHash(action, c.nonce, null), c.hash);
    same(await sig(hl.l1Digest(action, c.nonce, c.mainnet, null)), c.sig);
  });
}
for (const c of V.user) {
  test(`user-signed action matches the official SDK: ${c.name}`, async () => {
    same(await sig(hl.userDigest(hl.userAction(c.type, c.fields, true))), c.sig);
  });
}

test('float_to_wire parity (trailing zeros stripped, never "-0")', () => {
  for (const [x, want] of [[100, '100'], [0.1, '0.1'], [1e-8, '0.00000001'], [123456.789, '123456.789'], [-0, '0'], [2000.5, '2000.5']]) assert.equal(hl.floatToWire(x), want);
  assert.throws(() => hl.floatToWire(1e-9), /rounding/);
});

test('msgpack encodes integers above 2^32 exactly like the Python SDK (uint64, not float64)', () => {
  // Reference bytes from python msgpack.packb of the same object (hyperliquid-python-sdk uses msgpack).
  const big = { type: 'cancel', cancels: [{ a: 1, o: 50000000000 }, { a: 2, o: 4294967296 }, { a: 3, o: 4294967295 }] };
  assert.equal(Buffer.from(msgpack(big)).toString('hex'), '82a474797065a663616e63656ca763616e63656c739382a16101a16fcf0000000ba43b740082a16102a16fcf000000010000000082a16103a16fceffffffff');
});

test('cross-check against the community SDK @nktkas/hyperliquid (dev dependency, optional)', async (t) => {
  let sdk; let account;
  try { sdk = await import('@nktkas/hyperliquid/signing'); account = (await import('viem/accounts')).privateKeyToAccount(V.key); } catch { return t.skip('@nktkas/hyperliquid is not installed'); }
  for (const c of V.l1) {
    assert.equal(sdk.createL1ActionHash({ action: c.action, nonce: c.nonce }), c.hash, c.name);
    same(await sdk.signL1Action({ wallet: account, action: c.action, nonce: c.nonce, isTestnet: !c.mainnet }), c.sig);
  }
});
